content:
/* Rendered Markdown has no class hooks, so its look is set by tag under one root. */
.prose {
  min-width: 0;
  max-width: 52rem;
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.6;
  overflow-wrap: anywhere;
}

.prose :is(h1, h2, h3, h4, h5, h6) {
  font-family: var(--font-display);
  font-weight: 600;
  line-height: 1.25;
}
.prose h1 {
  margin-top: 0.5rem;
  font-size: 1.5rem;
}
.prose h2 {
  margin-top: 0.5rem;
  font-size: 1.25rem;
}
.prose h3 {
  margin-top: 0.25rem;
  font-size: 1.0625rem;
}

.prose ul {
  list-style: disc;
  padding-left: 1.5rem;
}
.prose ul ul {
  list-style: circle;
}
.prose ol {
  list-style: decimal;
  padding-left: 1.75rem;
}
.prose li[data-rest],
.prose li[data-task] {
  list-style: none;
}
.prose li[data-task] {
  position: relative;
}
.prose li[data-task] > input {
  position: absolute;
  top: 0.35em;
  left: -1.35em;
}

.prose blockquote {
  border-left: 3px solid var(--border);
  padding-left: 0.75rem;
  color: var(--muted-foreground);
}

.prose strong {
  font-weight: 600;
}
.prose a,
.prose [data-link] {
  color: var(--primary);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.prose [data-link] {
  cursor: help;
  text-decoration-style: dotted;
}
.prose [data-image] {
  cursor: help;
  color: var(--muted-foreground);
  font-style: italic;
}
.prose img {
  display: inline-block;
  max-width: 100%;
  height: auto;
}
.prose summary {
  cursor: pointer;
  font-weight: 600;
}
.prose kbd {
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 0.05em 0.35em;
  font-family: var(--font-mono);
  font-size: 0.85em;
}

/* A code block: Pierre draws the lines on a clear canvas, the block draws the card under them. */
.code {
  --diff-canvas: transparent;
  overflow: hidden;
  border-radius: 6px;
  background: color-mix(in srgb, var(--diff-fg) 5%, transparent);
  padding: 0.25rem 0;
}
/* Pierre's element paints its own canvas. The variable above does not reach that one rule. */
.code > * {
  background-color: transparent;
}

.prose code {
  border-radius: 4px;
  background: color-mix(in srgb, var(--diff-fg) 8%, transparent);
  padding: 0.1em 0.3em;
  font-family: var(--font-mono);
  font-size: 0.9em;
}
.prose pre {
  overflow-x: auto;
  border-radius: 6px;
  background: color-mix(in srgb, var(--diff-fg) 5%, transparent);
  padding: 0.5rem 0.75rem;
  font-family: var(--font-mono);
  font-size: var(--diff-font-size);
  line-height: var(--diff-line-height);
}
.prose[data-wrap] pre {
  white-space: pre-wrap;
}
.prose pre code {
  background: none;
  padding: 0;
  font-size: inherit;
}

.prose table {
  display: block;
  overflow-x: auto;
  border-collapse: collapse;
  /* A narrow column scrolls the table. It does not break a word. */
  overflow-wrap: normal;
}
.prose :is(th, td) {
  border: 1px solid var(--border);
  padding: 0.25rem 0.6rem;
  vertical-align: top;
}
.prose th {
  font-weight: 600;
}

.prose hr {
  margin: 0.5rem 0;
  border: 0;
  border-top: 1px solid var(--border);
}

/* The words that differ, on top of the tint that marks the whole block. */
.prose mark {
  border-radius: 2px;
  background: var(--md-mark);
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
  padding: 1px 0;
  color: inherit;
}
